package com.astra.tvhome;
import android.graphics.*;import android.view.*;import android.widget.*;
/** Local, mirrored preview. Frames are never recorded. A tiny live texture also drains hidden previews. */
final class CameraPreview extends FrameLayout {
    final MainActivity a;final TextureView texture;final Overlay overlay;float[][][] points=new float[0][][];
    CameraPreview(MainActivity a){super(a);this.a=a;texture=new TextureView(a);texture.setScaleX(-1);addView(texture,new LayoutParams(-1,-1));overlay=new Overlay(a);addView(overlay,new LayoutParams(-1,-1));setVisibility(GONE);setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);texture.setSurfaceTextureListener(new TextureView.SurfaceTextureListener(){public void onSurfaceTextureAvailable(SurfaceTexture t,int w,int h){}public void onSurfaceTextureSizeChanged(SurfaceTexture t,int w,int h){}public boolean onSurfaceTextureDestroyed(SurfaceTexture t){if(a.hands!=null&&a.hands.active)a.stopCamera();return true;}public void onSurfaceTextureUpdated(SurfaceTexture t){}});}
    void show(boolean on){boolean full=a.pref().getBoolean("cameraPreview",true);FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(a.dp(full?264:1),a.dp(full?198:1),Gravity.RIGHT|Gravity.BOTTOM);p.setMargins(0,0,a.dp(40),a.dp(126));setLayoutParams(p);setAlpha(full?1:.01f);setVisibility(on?VISIBLE:GONE);}
    final class Overlay extends View {Paint p=new Paint(3);Overlay(MainActivity a){super(a);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setColor(0xb606101c);c.drawRect(0,h-a.dp(32),w,h,p);p.setColor(0xffc5f3ff);p.setTextSize(a.dp(13));c.drawText(points.length>0?"已识别 "+points.length+" 只手":"请将手移入预览画面",a.dp(8),h-a.dp(6),p);p.setStrokeWidth(a.dp(1));for(float[][] hand:points){for(int[] edge:new int[][]{{0,1},{1,2},{2,3},{3,4},{0,5},{5,6},{6,7},{7,8},{5,9},{9,10},{10,11},{11,12},{9,13},{13,14},{14,15},{15,16},{13,17},{0,17},{17,18},{18,19},{19,20}})c.drawLine((1-hand[edge[0]][0])*w,hand[edge[0]][1]*h,(1-hand[edge[1]][0])*w,hand[edge[1]][1]*h,p);for(float[] point:hand)c.drawCircle((1-point[0])*w,point[1]*h,a.dp(1.6f),p);}}}
}
